module four_bit_adder_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [4:0] SUM
);

    // Combinational DUT with no RTL clock or reset; sample on external clk.
    function automatic logic fa_cout (
        input logic x,
        input logic y,
        input logic cin
    );
        fa_cout = (x & (y | cin)) | (y & cin);
    endfunction

    // SUM[0] matches the first full-adder sum bit.
    check_sum_bit0: assert property (
        @(posedge clk) SUM[0] == (A[0] ^ B[0] ^ 1'b0)
    );

    // SUM[1] uses the carry generated by bit 0.
    check_sum_bit1: assert property (
        @(posedge clk)
        SUM[1] == (A[1] ^ B[1] ^ fa_cout(A[0], B[0], 1'b0))
    );

    // SUM[2] uses the carry generated by bit 1.
    check_sum_bit2: assert property (
        @(posedge clk)
        SUM[2] == (A[2] ^ B[2] ^
                   fa_cout(A[1], B[1], fa_cout(A[0], B[0], 1'b0)))
    );

    // SUM[3] uses the carry generated by bit 2.
    check_sum_bit3: assert property (
        @(posedge clk)
        SUM[3] == (A[3] ^ B[3] ^
                   fa_cout(A[2], B[2],
                           fa_cout(A[1], B[1], fa_cout(A[0], B[0], 1'b0))))
    );

    // SUM[4] is the final carry-out of the ripple chain.
    check_final_carry: assert property (
        @(posedge clk)
        SUM[4] == fa_cout(A[3], B[3],
                          fa_cout(A[2], B[2],
                                  fa_cout(A[1], B[1], fa_cout(A[0], B[0], 1'b0))))
    );

    // The 5-bit output equals the arithmetic sum of A and B.
    check_total_sum: assert property (
        @(posedge clk) SUM == ({1'b0, A} + {1'b0, B})
    );

endmodule